        number: 3,
        title: 'Tajalli - Le sommeil comme miroir de l\'ame',
        content: `## Ce que votre insomnie revele

Le Tajalli pour le sommeil vous invite a contempler vos troubles du sommeil dans la lumiere du Coran. L'insomnie n'est pas seulement un probleme medical ou biologique. C'est un miroir qui revele l'etat de votre ame. La nuit, quand les distractions du jour disparaissent, l'ame se montre telle qu'elle est. Et si elle ne peut pas dormir, c'est qu'elle porte quelque chose qui l'empeche de se reposer.

Le mot arabe pour « repos » dans le Coran est *sakina* (سَكِينَة), qui signifie littetralement « quietude », « tranquillite profonde ». La *sakina* est un don divin :

> « هُوَ ٱلَّذِىٓ أَنزَلَ ٱلسَّكِينَةَ فِى قُلُوبِ ٱلْمُؤْمِنِينَ »
>
> « C'est Lui qui a fait descendre la tranquillite (*sakina*) dans les coeurs des croyants. » (48:4)

Si la sakina peut descendre dans les coeurs, elle peut aussi en etre absente. L'insomnie, dans cette perspective, est l'absence temporaire de la sakina. Le Tajalli vous aide a comprendre pourquoi.

## Les quatre racines cachees de l'insomnie

Apres avoir accompagne de nombreuses personnes dans leur quete de sommeil, un schema se degage. L'insomnie a quatre racines principales, chacune correspondant a un desordre de l'ame que le Coran peut eclairer.

### 1. L'exces de responsabilite : « Le porteur du monde »

Vous portez le poids du monde sur vos epaules et vous n'arrivez pas a le poser. La nuit, quand tout est calme, le poids devient insupportable car il n'y a plus d'activite pour le masquer.

> La nuit dit : « Je ne peux pas dormir, il y a trop a faire. »
> Le Coran repond : « وَلَسَوْفَ يُعْطِيكَ رَبُّكَ فَتَرْضَىٰٓ » — « Ton Seigneur va te donner, et tu seras satisfait. » (93:5)

Ce verset, revele au Prophete dans les moments les plus difficiles de sa mission, est une promesse divine : Allah pourvoit. Vous n'avez pas besoin de tout porter. L'insomnie de la responsabilite cache souvent un orgueil spirituel subtil : « Si je ne le fais pas, personne ne le fera. » Or, Allah est *Al-Wakil* (Le Garant). Il n'a pas besoin de vous pour faire tourner le monde.

### 2. Le manque de confiance en l'avenir : « Le projeteur anxieux »

L'insomnie est souvent liee a la peur du lendemain. Que va-t-il se passer ? Et si les choses tournent mal ? Et si je perds mon emploi ? Et si... Le mental projette des scenarios catastrophes dans un futur qui n'existe pas encore.

> La nuit dit : « Demain sera terrible. »
> Le Coran repond : « وَمَن يَتَّقِ ٱللَّهَ يَجْعَل لَّهُۥ مَخْرَجًا » — « Et quiconque craint Allah, Il lui donnera une issue. » (65:2)

Ibn al-Qayyim dit : « Celui qui fait confiance a Allah dort comme un enfant, car il sait que son avenir est entre les meilleures mains. Et celui qui ne fait pas confiance a Allah veille comme un veilleur de nuit, car il croit que tout depend de lui. »

### 3. Les emotions non traitees : « Le repertoire nocturne »

La nuit, quand les distractions disparaissent, les emotions refoulees remontent a la surface. Si vous avez accumule de la tristesse, de la peur ou de la colere pendant la journee sans les traiter, elles vous garderont eveille. Le sommeil est le moment ou le corps traite les emotions du jour. Si le reservoir est trop plein, le traitement ne peut pas se faire.

> La nuit dit : « Je suis trop triste / en colere / effraye(e) pour dormir. »
> Le Coran repond : « وَهُوَ ٱلَّذِىٓ أَنزَلَ ٱلسَّكِينَةَ فِى قُلُوبِ ٱلْمُؤْمِنِينَ » — « C'est Lui qui a fait descendre la tranquillite dans les coeurs des croyants. » (48:4)

La sakina ne descend pas dans un coeur qui est rempli d'emotions non reconnues. La premiere etape est de nommer ce que vous ressentez, pas de le chasser.

### 4. La peur de la mort : « Le petit frere de la mort »

Le sommeil etant le « frere de la mort », l'insomnie peut cacher une peur inconsciente de mourir. S'endormir, c'est faire l'experience de l'abandon total, du lacher-prise absolu. Pour une personne traumatisee, cet abandon peut etre terrifiant.

> La nuit dit : « Si je m'endors, je ne me reveillerai peut-etre pas. »
> Le Coran repond : « ٱللَّهُ يَتَوَفَّى ٱلْأَنفُسَ حِينَ مَوْتِهَا وَٱلَّتِى لَمْ تَمُتْ فِى مَنَامِهَا ۖ فَيُمْسِكُ ٱلَّتِى قَضَىٰ عَلَيْهَا ٱلْمَوْتَ وَيُرْسِلُ ٱلْأُخْرَىٰٓ إِلَىٰٓ أَجَلٍ مُّسَمًّى » — « Allah retient les ames au moment de leur mort, ainsi que celles qui ne meurent pas pendant leur sommeil. Il retient celle dont Il a decrete la mort et relache l'autre jusqu'a un terme fixe. » (39:42)

Ce verset est extraordinairement precis : Allah retient votre ame pendant le sommeil. Il ne la laisse pas echapper. Dormir, c'est remettre son ame entre les mains de Celui qui la retient. Quelle plus grande securite ?

## La technique du Tajalli nocturne : les cinq regards

Choisissez un verset qui resonne avec la racine de votre insomnie. Puis pratiquez les cinq regards :

- **Premier regard** : Qu'est-ce que ce verset me dit sur ma nuit ? Lisez-le comme s'il avait ete revele pour cette nuit precise, pour cette insomnie exacte.

- **Deuxieme regard** : Qu'est-ce que ce verset me dit sur moi a travers mon insomnie ? Mon insomnie revele-t-elle une responsabilite excessive ? Un manque de confiance ? Des emotions non traitees ? Une peur cachee ?

- **Troisieme regard** : Qu'est-ce que ce verset me dit sur Allah en relation avec mon sommeil ? Est-Il absent la nuit ? Ou est-Il, comme le verset 39:42 le montre, Celui qui retient les ames pendant que je dors ?

- **Quatrieme regard** : Si ce verset est une verite divine, comment se retourne-t-il vers moi ? Le verset parle de la *sakina* : ou en moi la tranquillite fait-elle defaut ? Le verset parle de la provision : suis-je en train de Porter le fardeau d'Allah au lieu de porter le mien ?

- **Cinquieme regard** : *[Silence]*. Ne cherchez plus rien. Restez dans l'ecoute. Parfois, le cinquieme regard produit le sommeil lui-meme : un glissement doux, une disparition de la veille. Accueillez-le.

## Journal de Tajalli

- Quelle racine d'insomnie avez-vous identifiee ?
- Quel verset-miroir avez-vous choisi et pourquoi ?
- Que vous a revele le deuxieme regard sur vous-meme ?
- Avez-vous atteint le cinquieme regard ? Que s'y est passe ?`,
