        title: 'Tajalli - La solitude comme espace sacre',
        content: `## Le desert est un lieu de revelation

Le Tajalli pour la solitude transforme radicalement notre rapport a l'isolement. Car dans la tradition islamique, la solitude n'est pas un defaut : c'est le lieu privilegie de la revelation. Toutes les grandes revelations ont eu lieu dans la solitude : la grotte de Hira pour Muhammad, le Mont Sinai pour Moussa, le desert pour Ibrahim, la prison pour Yusuf. Le desert n'est pas l'absence de vie : c'est le lieu ou la vie se revele dans sa forme la plus pure.

La solitude est un miroir. Ce n'est pas elle qui guérit : c'est ce qu'elle revele. Comme un miroir qui montre une poussiere que vous ne voyiez pas, la solitude montre des aspects de vous-meme qui demandent attention. Et ce miroir a deux faces : une face humaine et une face divine. Le Tajalli vous apprend a lire les deux.

## Le principe du miroir : la solitude revelatrice

Quand vous etes entoure de gens, votre attention est constamment sollicitee par les besoins et les expectatives des autres. Vous ne pouvez pas vraiment voir qui vous etes car il y a trop de bruit exterieur. La solitude enleve ce bruit et revele votre veritable etat interieur.

Si la solitude vous fait souffrir, c'est que votre interieur porte des blessures que la presence des autres masquait. Si la solitude vous apaise, c'est que votre interieur est deja un espace de paix. La solitude ne cree pas ces etats : elle les revele.

**Ibn al-Qayyim** ecrit dans *Madarij al-Salikin* : « La solitude est le miroir du coeur. Le coeur brise se voit dans la solitude et pleure. Le coeur pur se voit dans la solitude et sourit. Mais les deux sont guéris, car celui qui pleure sera console et celui qui sourit sera renforce. »

## Les versets-miroirs pour chaque type de solitude

Choisissez un verset qui resonne avec votre experience. Voici le tableau de correspondance :

| Type de solitude | Verset-miroir | Reference |
|---|---|---|
| Solitude qui fait souffrir | « N'aie pas peur, tu ne seras pas humilie. Ne sois pas afflige, tu ne seras pas couvert d'opprobre. » | 20:44 |
| Solitude spirituelle | « Et rappelle-toi ton Seigneur en toi-meme, avec humilite et crainte. » | 7:205 |
| Sentiment d'abandon | « Mon fils, ne te repais pas de tes yeux, ne t'afflige pas pour eux. » | 31:17 |
| Recherche de sens | « Je me refugie aupres de Celui qui m'a cree, contre le mal de ce que je ressens. » | 41:36 |
| Confiance en la presence divine | « Et quand Mes serviteurs t'interrogent sur Moi, alors Je suis tout proche. » | 2:186 |
| Tranquillite dans la solitude | « Et Il est avec vous ou que vous soyez. » | 57:4 |

## La contemplation en cinq regards (15 min)

Lisez le verset lentement, a voix basse, en laissant chaque mot ressonner dans votre poitrine. Puis passez par les cinq regards :

**Premier regard : La solitude elle-meme.** Qu'est-ce que ce verset me dit sur MA solitude ? Pas sur la solitude en general, sur VOTRE solitude, celle que vous portez en ce moment. Lisez le verset comme s'il avait ete revele pour cette nuit precise, pour cette piece precise, pour cette douleur precise.

> « وَإِذَا سَأَلَكَ عِبَادِي عَنِّي فَإِنِّي قَرِيبٌ أُجِيبُ دَعْوَةَ الدَّاعِ إِذَا دَعَانِ »
> « Et quand Mes serviteurs t'interrogent sur Moi, alors Je suis tout proche. » (2:186)

Ce verset n'a pas de condition. Il ne dit pas « Je suis proche si tu pries » ou « Je suis proche si tu es bon(ne) ». Il dit « quand Mes serviteurs t'interrogent sur Moi » : c'est-a-dire quand ils se demandent ou est Allah, quand ils doutent de Sa proximite, quand la solitude leur fait croire a Son absence. La reponse est immediate : « Je suis tout proche. »

**Deuxieme regard : Ce que la solitude revele sur moi.** Que me dit ce verset a travers ma solitude ? Ma solitude revele peut-etre que je cherche la presence humaine comme preuve de ma valeur. Si personne n'est la, je me sens de valeur nulle. Mon estime de soi depend du regard des autres. Le verset me revele que ma vraie valeur est dans le regard de Celui qui ne quitte jamais : « Je suis tout proche. »

**Troisieme regard : Ce que la solitude revele sur Allah.** Si Allah permet cette solitude dans ma vie, qu'est-ce qu'Il m'invite a decouvrir ? Peut-etre qu'Il m'invite a decouvrir que Sa compagnie suffit ? Que je peux etre complet(e) meme seul(e), car Celui qui est present avec moi est le Seigneur de l'univers ? La solitude est-elle un manque ou une invitation ?

**Quatrieme regard : Le retournement.** Si ce verset est une verite divine, comment se retourne-t-il vers moi ? Le verset dit qu'Allah est proche. Oi en moi existe-t-il un manque de proximite avec Lui ? Est-ce ma solitude qui m'eloigne de Lui, ou est-ce moi qui m'eloigne de Lui dans ma solitude ? Peut-etre que la solitude est une porte que j'ai toujours vue comme fermee, alors qu'elle est entrouverte.

**Cinquieme regard : Le silence.** Ne cherchez plus rien. Restez dans l'ecoute. Parfois, le cinquieme regard ne produit pas de mots mais une sensation : de la chaleur, de la legérete, des larmes, un soupir profond. Accueillez ce qui vient.

## Exemple : Le Tajalli sur la solitude du soir

**Verset** : « وَهُوَ مَعَكُمْ أَيْنَ مَا كُنتُمْ »
« Et Il est avec vous ou que vous soyez. » (57:4)

**Premier regard** : Allah est avec moi dans cette piece vide. « Oi que vous soyez » : dans ma solitude, dans mon lit, dans mon silence. Il n'y a pas de lieu ou Il n'est pas.

**Deuxieme regard** : Ma solitude du soir revele que je ressens un manque : le manque d'un(e) compagnon/compagne, le manque d'une voix, le manque d'un regard. Mais ce manque est-il vraiment un manque, ou est-ce le souvenir d'un attachement que je n'ai pas encore lache ?

**Troisieme regard** : Si Allah est avec moi, pourquoi est-ce que je me sens si seul(e) ? Est-ce parce que je ne Le sens pas ? Mais le Coran ne dit pas « Je suis avec vous quand vous Me sentez ». Il dit « Je suis avec vous ». Point final. Le sentiment n'est pas la condition.

**Quatrieme regard** : Si la presence divine est independante de ma capacite a la ressentir, alors ma solitude n'est pas un probleme de presence : c'est un probleme de perception. Mon coeur est aveugle a une lumiere qui brille en permanence. Le Tajalli est le nettoyage du miroir du coeur pour que la lumiere puisse etre vue.

**Cinquieme regard** : *[Silence]*

> « لَا تَحْزَنْ إِنَّ اللَّهَ مَعَنَا »
> « Ne sois pas triste. Allah est avec nous. » (9:40)

Ce verset a ete prononce par un compagnon du Prophete au coeur de la grotte, quand ils etaient tous les deux en fuite et purs. Il est votre verset dans votre solitude.

## Journal de Tajalli

- Quel verset-miroir avez-vous choisi et pourquoi ?
- Que vous a-t-il revele sur votre rapport a la solitude que vous ne saviez pas ?
- Ecrivez une « lecture inversee » : prenez votre pensee la plus douloureuse sur la solitude et opposez-lui la verite coranique.
- Parmi les quatre racines de la souffrance de la solitude (chapitre 1), laquelle le Tajalli a-t-il mise en lumiere ?`,
