        id: 'tat-3',
        number: 3,
        title: 'Tajalli - Le Coran miroir de vos liens',
        content: `## Ce que vos relations revelent sur votre coeur

Le Tajalli pour les blessures d'attachement est une revelation profonde. Car vos relations ne sont pas simplement des evenements de votre vie : elles sont des miroirs qui refletent l'etat de votre coeur. Et le Coran est le miroir supreme qui vous permet de lire avec clarte ce que vos relations revelent.

Ibn al-Qayyim ecrit :

> « Chaque personne que tu rencontres est un verset d'Allah. L'un te montre ta patience. L'autre te montre ta colere. Un troisieme te montre ta peur. Et chacun d'eux est un enseignement que Allah t'envoie pour te faire connaitre toi-meme. »

## Le Coran et les relations familiales

Le Coran accorde une importance immense aux relations familiales. Il regorge d'histoires de relations parent-enfant qui servent de modeles de guerison et de transformation :

**L'histoire de Luqman et de son fils (sourate 31)** : un pere sage qui conseille son fils avec douceur et bienveillance. Il ne le controle pas, ne le rejette pas, ne l'abandonne pas. Il lui enseigne avec amour et le laisse faire ses propres choix.

> « يَا بُنَيَّ أَقِمِ الصَّلَاةَ وَأْمُرْ بِالْمَعْرُوفِ وَانْهَ عَنِ الْمُنكَرِ وَاصْبِرْ عَلَىٰ مَا أَصَابَكَ إِنَّ ذَٰلِكَ مِنْ عَزْمِ الْأُمُورِ »
> « O mon fils, accomplis la priere, ordonne le bien, interdis le mal et endure ce qui t'atteint. Cela fait partie des choses fermement recommandees. » (31:17)

**L'histoire de la mere de Moussa (sourate 28)** : l'amour maternel dans sa forme la plus pure, un amour qui traverse la peur, la separation, et qui finit par triompher car il est soutenu par la foi en Allah.

**L'histoire de Ya'qub et Yusuf (sourate 12)** : un lien parent-enfant qui survit a la trahison, a la separation, et a des annees de douleur. Ce lien est si fort qu'il peut supporter l'epreuve la plus extreme et se renouveler au moment de la reunion.

## Les versets-miroirs pour chaque blessure d'attachement

Choisissez un verset qui resonne avec votre blessure :

| Blessure | Verset-miroir | Reference |
|---|---|---|
| Abandon | « Ton Seigneur va te donner, et tu seras satisfait. » | 93:5 |
| Rejet | « Ne te laisse pas abattre, ne t'afflige pas, alors que tu es les superieurs, si vous etes des croyants. » | 3:139 |
| Maltraitance | « C'est par la misericorde d'Allah que tu as ete doux envers eux. » | 3:159 |
| Surprotection | « Et quiconque place sa confiance en Allah, Il lui suffit. » | 65:3 |
| Guerison du lien | « Et Ton Seigneur a decretee : N'adorez que Lui. Et (Il a decretee) la bonte envers les parents. » | 17:23 |

## La contemplation en cinq regards sur l'histoire de Yusuf

L'histoire de Yusuf (sourate 12) est peut-etre le recit coranique le plus riche en matiere d'attachement. Yusuf a ete abandonne par ses freres, vendu comme esclave, faussement accuse, emprisonne. Et pourtant, il est devenu un ministre puissant et a guerit ses relations familiales. Son secret ? La confiance en Allah a chaque etape, meme dans les moments les plus sombres.

**Lisez ce verset avant de commencer :**

> « وَلَقَدْ أَنزَلْنَا إِلَيْكَ آيَاتٍ بَيِّنَاتٍ وَمَثَلًا مِّنَ الَّذِينَ خَلَوْا مِن قَبْلِكَ وَمَوْعِظَةً لِّلْمُتَّقِينَ »
> « Et Nous avons fait descendre vers toi des versets clairs, et l'exemple de ceux qui ont vecu avant toi, et une exhortation pour les pieux. » (24:34)

**Premier regard : La blessure de Yusuf.** Yusuf a ete abandonne par ses propres freres, jetes dans un puits, puis vendu comme esclave. C'est la blessure d'abandon dans sa forme la plus extreme : trahi par sa propre famille. Et pourtant, le Coran ne decrit pas Yusuf comme une victime. Il le decrit comme un homme de confiance :

> « وَكَذَٰلِكَ مَكَّنَّا لِيُوسُفَ فِي الْأَرْضِ وَلِنُعَلِّمَهُ مِن تَأْوِيلِ الْأَحَادِيثِ »
> « C'est ainsi que Nous avons etabli Yusuf dans le pays. » (12:21)

**Deuxieme regard : Ce que cette histoire revele sur ma blessure.** Comme Yusuf, j'ai ete blesse par ceux qui auraient du me proteger. Et comme lui, j'ai peut-etre developpe un schema de survie : la confiance absolue en Allah, ou au contraire, la mefiance totale envers les autres. Qu'est-ce que mon schema actuel a en commun avec celui de Yusuf ? En quoi est-il different ?

**Troisieme regard : La confiance de Yusuf comme modele.** A chaque etape de son epreuve, Yusuf s'en remet a Allah. Dans le puits : « Tu es mon meilleur gardien. » En prison : « Le jugement n'appartient qu'a Allah. » Face a la tentation : « O Allah, je prefere la prison a ce qu'ils m'appellent a faire. » Cette confiance n'est pas naive : c'est une confiance eprouvee par le feu.

**Quatrieme regard : Le retournement vers moi.** Si Yusuf a pu guerir sa blessure d'abandon par la confiance en Allah, pourquoi est-ce que je ne le peux pas ? Oi est-ce que je refuse de faire confiance ? Quelle peur me retient ? Est-ce la peur d'etre blesse a nouveau ? Mais la confiance en Allah ne protege pas de la blessure : elle protege de la destruction par la blessure.

**Cinquieme regard : La reunion.** La reunion de Yusuf avec son pere Ya'qub est l'un des passages les plus emouvants du Coran :

> « اذْهَبُوا بِقَمِيصِي هَٰذَا فَأَلْقُوهُ عَلَىٰ وَجْهِ أَبِي يَأْتِ بَصِيرًا »
> « Retirez cette chemise de dessus mon visage et jetez-la sur le visage de mon pere, il recouvrira la vue. » (12:93)

Cette chemise, symbole du lien entre pere et fils, guerit la cecite de Ya'qub. Le Coran enseigne ainsi que les liens d'attachement blesses peuvent etre gueris, meme apres des annees de separation. *[Silence]*

## L'exercice du miroir relationnel

Choisissez une relation difficile dans votre vie. Puis posez-vous cette question radicale :

**« Est-ce que ce qui me blesse chez l'autre est quelque chose que je refuse de voir en moi-meme ? »**

- L'autre est « trop exigeant » : ne suis-je pas aussi exigeant(e) envers moi-meme ?
- L'autre est « trop distant » : ne suis-je pas aussi distant(e) avec mes propres emotions ?
- L'autre est « trop controlant » : ne cherche-je pas aussi a tout controler ?

Ce n'est pas toujours vrai. Mais c'est souvent surprenant.

## Journal de Tajalli

- Quel verset avez-vous choisi pour votre blessure d'attachement ?
- Que vous a-t-il revele sur vos relations actuelles que vous ne saviez pas ?
- L'histoire de Yusuf vous a-t-elle touche(e) ? Quel aspect en particulier ?
- Qu'avez-vous decouvert dans l'exercice du miroir relationnel ?`,
